"use client"

import React, { useState, useEffect } from 'react'
import { GoogleAuthProvider, signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import { auth } from '@/lib/Firebase';
import { db } from '@/lib/Firebase';
import { doc, setDoc } from 'firebase/firestore';

function page() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    idea: '',
  });

  const [user, setUser] = useState<User | null>(null);

  const provider = new GoogleAuthProvider(); // Create a Google Auth provider instance

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    console.log(formData);

    // logic
    signInWithPopup(auth, provider)
      .then((result) => {
        // This gives you a Google Access Token. You can use it to access the Google API.
        const credential = GoogleAuthProvider.credentialFromResult(result);
        const token = credential?.accessToken;
        // The signed-in user info.
        const user = result.user;
        console.log("Google Sign-In successful! ",user);

        setUser(user);

        // Add user to Firestore
        const docRef = doc(db, "attendees", user.uid);
        setDoc(docRef, {
          email: user.email,
          idea: formData.idea,
          name: user.displayName,
        });

        console.log("User added to Firestore!", docRef);
      })
      .catch((error) => {
        // Handle Errors here.
        const errorCode = error.code;
        const errorMessage = error.message;
        // The email of the user's account used.
        const email = error.email;
        // The AuthCredential type that was used.
        const credential = GoogleAuthProvider.credentialFromError(error);
        console.log("Google Sign-In failed! ",errorCode, errorMessage);
      });
    
  };

  const handleSignOut = () => {
    signOut(auth)
      .then(() => {
        console.log("User signed out successfully!");
      })
      .catch((error) => {
        console.log("Error signing out: ", error);
      });
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      if (user) {
        console.log("User is signed in!", user);
        setUser(user);
      } else {
        console.log("User is signed out!");
        setUser(null);
      }
    });

    return () => unsubscribe();
  }, []);


  
  return (
    <div className='flex min-h-screen items-center justify-center bg-white font-sans dark:bg-black'>
      <form onSubmit={handleSubmit} className='flex flex-col gap-4 border-2 p-10 rounded-md'>
        {/* show label and email if logged in */}
        {user && (
          <>
            <p>{user.email}</p>
            <p>{user.displayName}</p>
          </>
        )}
        <label htmlFor="name">Name</label>
        <input type="text" id="name" name="name" onChange={handleChange} className='rounded-md border border-gray-300 p-2' />

        <label htmlFor="email">Email</label>
        <input type="email" id="email" name="email" onChange={handleChange} className='rounded-md border border-gray-300 p-2' />

        <label htmlFor="idea">Idea</label>
        <textarea name="idea" id="idea" onChange={handleChange} className='rounded-md border border-gray-300 p-2'></textarea>

        <button type="submit" className='rounded-md bg-blue-500 p-2'>Submit</button>

        <button type="button" onClick={handleSignOut} className='rounded-md bg-red-500 p-2'>Sign Out</button>
      </form>
    </div>
  )
}

export default page

